const fs = require('fs');

async function main() {
    const result = {
        chain: "base-sepolia",
        type: "evm-smart-wallet",
        address: "mock-address"
    };

    try {
        let sdk;
        try {
            sdk = require("@crossmint/wallets-sdk");
        } catch (e) {
            sdk = await import("@crossmint/wallets-sdk");
        }

        const apiKey = process.env.CROSSMINT_API_KEY;
        const signerSecret = process.env.SIGNER_SECRET;

        if (!apiKey || !signerSecret) {
            throw new Error("Missing credentials. Please provide CROSSMINT_API_KEY and SIGNER_SECRET.");
        }

        // Initialize Crossmint
        const crossmint = new sdk.Crossmint({ apiKey });

        // Create wallet
        const wallet = await crossmint.wallets.create({
            chain: "base-sepolia",
            type: "evm-smart-wallet",
            signer: {
                type: "server",
                secret: signerSecret
            }
        });

        if (wallet && wallet.address) {
            result.address = wallet.address;
        }

    } catch (error) {
        result.error = error.message;
    }

    fs.writeFileSync('/home/user/wallet_result.json', JSON.stringify(result, null, 2));
    console.log("Log written to /home/user/wallet_result.json");
}

main().catch(console.error);

